struct sembuf {
    unsigned short sem_num;
    short sem_op;
    short sem_flg;
};

int semid = 42; // Semaphore Set Identifier

// 1. Lock (Decrement, Wait)
struct sembuf P_op = {
    0,    // sem_num (Index 0)
    -1,   // sem_op (Decrement)
    SEM_UNDO // sem_flg
};

// 2. Unlock (Increment)
struct sembuf V_op = { 0, 1, SEM_UNDO };

// 3. Wait For Zero
struct sembuf Z_op = { 0, 0, IPC_NOWAIT };

// Execute one atomic operation (Lock)
int ret = semop(semid, &P_op, 1);

// Execute a sequence of operations (e.g., Lock then Wait for Zero)
struct sembuf ops[] = { P_op, Z_op };
